SELECT , o.order_no, o.receiver_name
FROM logistics l
LEFT JOIN orders o ON l.order_id = o.id


        AND l.logistics_no LIKE CONCAT('%', #{logisticsNo}, '%')


        AND l.order_id = #{orderId}


        AND l.status = #{status}


        AND l.logistics_company = #{logisticsCompany}


ORDER BY l.create_time DESC

